python3 -c "
import json
with open('/app/resources/treasury_bulletin_2007_12.json', 'r') as f:
    data = json.load(f)

# Look at pages
pages = data.get('document', {}).get('pages', [])
print(f'Number of pages: {len(pages)}')

# Look at first few pages
for i, page in enumerate(pages[:3]):
    print(f'\\nPage {i}: keys = {list(page.keys()) if isinstance(page, dict) else type(page)}')
    if isinstance(page, dict):
        for k, v in page.items():
            if isinstance(v, str):
                print(f'  {k}: {v[:200]}...' if len(v) > 200 else f'  {k}: {v}')
            elif isinstance(v, list):
                print(f'  {k}: list of {len(v)} items')
            else:
                print(f'  {k}: {v}')
"

