import json
with open('/app/resources/treasury_bulletin_2007_12.json', 'r') as f:
    data = json.load(f)

# Look at elements
elements = data.get('document', {}).get('elements', [])
print(f'Number of elements: {len(elements)}')

# Look at first few elements
for i, elem in enumerate(elements[:5]):
    print(f'\\nElement {i}: keys = {list(elem.keys()) if isinstance(elem, dict) else type(elem)}')
    if isinstance(elem, dict):
        for k, v in elem.items():
            if isinstance(v, str):
                print(f'  {k}: {v[:300]}...' if len(v) > 300 else f'  {k}: {v}')
            elif isinstance(v, list):
                print(f'  {k}: list of {len(v)} items')
            else:
                print(f'  {k}: {v}')
"

